CREATE TABLE IF NOT EXISTS tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, project_id UUID REFERENCES projects(id) ON DELETE CASCADE, parent_id UUID REFERENCES tasks(id) ON DELETE CASCADE, title TEXT NOT NULL, priority TEXT DEFAULT 'Medium', status TEXT DEFAULT 'Todo', due_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())